    { ar: "الوقف الحسن", latin: "al-waqf al-hasan", id: "Waqaf baik", def: { id: "Berkaitan lafzhan dan maknan; boleh berhenti, tak baik memulai sesudahnya.", ar: "تعلق لفظي ومعنوي." } },
    { ar: "الوقف القبيح", latin: "al-waqf al-qabih", id: "Waqaf buruk", def: { id: "Berhenti pada kalimat yang belum sempurna atau menimbulkan makna keliru.", ar: "على كلام لم يتم أو يوهم معنى فاسدًا." } },
    { ar: "المراقبة / المعانقة", latin: "al-muraqabah / al-mu'anaqah", id: "Dua waqaf saling berpelukan", def: { id: "Berhenti di salah satu dari dua tempat waqaf berdekatan, tidak di keduanya; tanda ∴.", ar: "إذا وقف على أحدهما امتنع الوقف على الآخر." } }
